class TestPerformance:
    """Ensure conftest doesn't introduce performance bottlenecks."""

    def test_import_time(self, isolated_conftest_module):
        """Import should complete quickly (< 1 second)."""
        import time
        start = time.perf_counter()
        spec = importlib.util.spec_from_file_location("isolated_conftest_perf", CONFTEST_PATH)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        elapsed = time.perf_counter() - start
        assert elapsed < 1.0, f"Import took {elapsed:.2f}s"

    def test_memory_footprint(self, isolated_conftest_module):
        """Import should not consume excessive memory."""
        import tracemalloc
        tracemalloc.start()
        spec = importlib.util.spec_from_file_location("isolated_conftest_mem", CONFTEST_PATH)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        current, peak = tracemalloc.get_traced_memory()
        tracemalloc.stop()
        assert peak < 10 * 1024 * 1024, f"Peak memory {peak / 1024 / 1024:.1f}MB exceeds 10MB"


